-- SPECIFICATION ONLY: identity_db. IDs generated by application. Not executed.
CREATE SCHEMA identity;

CREATE TABLE identity.users (
  user_id uuid PRIMARY KEY,
  email varchar(320) NOT NULL UNIQUE,
  password_hash text NOT NULL,
  display_name varchar(120) NOT NULL,
  avatar_object_key text,
  status varchar(20) NOT NULL DEFAULT 'PENDING',
  email_verified_at timestamptz,
  locale varchar(16) NOT NULL DEFAULT 'vi-VN',
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  CHECK (email = lower(btrim(email))),
  CHECK (status IN ('PENDING','ACTIVE','SUSPENDED','DELETED')),
  CHECK ((status = 'DELETED') = (deleted_at IS NOT NULL))
);

CREATE TABLE identity.roles (
  role_code varchar(30) PRIMARY KEY,
  name varchar(100) NOT NULL,
  CHECK (role_code IN ('USER','BUSINESS','ADMIN'))
);

CREATE TABLE identity.user_roles (
  user_id uuid NOT NULL REFERENCES identity.users(user_id) ON DELETE CASCADE,
  role_code varchar(30) NOT NULL REFERENCES identity.roles(role_code),
  assigned_at timestamptz NOT NULL DEFAULT now(),
  assigned_by uuid REFERENCES identity.users(user_id),
  PRIMARY KEY (user_id, role_code)
);

CREATE TABLE identity.user_preferences (
  user_id uuid PRIMARY KEY REFERENCES identity.users(user_id) ON DELETE CASCADE,
  budget_level varchar(12),
  budget_min numeric(14,2),
  budget_max numeric(14,2),
  currency char(3) NOT NULL DEFAULT 'VND',
  companion_type varchar(20),
  indoor_outdoor varchar(12),
  personalization_enabled boolean NOT NULL DEFAULT false,
  consent_version bigint NOT NULL DEFAULT 1 CHECK (consent_version > 0),
  consent_updated_at timestamptz NOT NULL DEFAULT now(),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (budget_level IN ('LOW','MID','HIGH','CUSTOM')),
  CHECK (budget_min IS NULL OR budget_min >= 0),
  CHECK (budget_max IS NULL OR budget_max >= 0),
  CHECK (budget_min IS NULL OR budget_max IS NULL OR budget_min <= budget_max),
  CHECK (currency ~ '^[A-Z]{3}$'),
  CHECK (companion_type IN ('SOLO','COUPLE','FAMILY','FRIENDS','GROUP')),
  CHECK (indoor_outdoor IN ('INDOOR','OUTDOOR','BOTH'))
);

CREATE TABLE identity.preference_options (
  option_id uuid PRIMARY KEY,
  kind varchar(24) NOT NULL CHECK (kind IN ('TRAVEL_STYLE','FOOD_PREFERENCE')),
  code varchar(64) NOT NULL,
  label_vi varchar(160) NOT NULL,
  active boolean NOT NULL DEFAULT true,
  UNIQUE (kind, code)
);

CREATE TABLE identity.user_preference_options (
  user_id uuid NOT NULL REFERENCES identity.user_preferences(user_id) ON DELETE CASCADE,
  option_id uuid NOT NULL REFERENCES identity.preference_options(option_id),
  PRIMARY KEY (user_id, option_id)
);

CREATE TABLE identity.user_category_preferences (
  user_id uuid NOT NULL REFERENCES identity.user_preferences(user_id) ON DELETE CASCADE,
  category_id uuid NOT NULL, -- external Catalog.categories
  weight numeric(5,4) NOT NULL DEFAULT 1 CHECK (weight BETWEEN 0 AND 1),
  PRIMARY KEY (user_id, category_id)
);

CREATE TABLE identity.auth_sessions (
  session_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES identity.users(user_id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  device_label varchar(160),
  CHECK (expires_at > created_at)
);

CREATE TABLE identity.refresh_tokens (
  token_id uuid PRIMARY KEY,
  session_id uuid NOT NULL REFERENCES identity.auth_sessions(session_id) ON DELETE CASCADE,
  token_hash text NOT NULL UNIQUE,
  parent_token_id uuid REFERENCES identity.refresh_tokens(token_id),
  issued_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  revoked_at timestamptz,
  CHECK (expires_at > issued_at),
  UNIQUE (parent_token_id)
);

CREATE TABLE identity.account_tokens (
  token_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES identity.users(user_id) ON DELETE CASCADE,
  purpose varchar(20) NOT NULL CHECK (purpose IN ('VERIFY_EMAIL','RESET_PASSWORD')),
  token_hash text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  CHECK (expires_at > created_at)
);

CREATE TABLE identity.notifications (
  notification_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES identity.users(user_id) ON DELETE CASCADE,
  source_event_id uuid NOT NULL,
  notification_type varchar(64) NOT NULL,
  payload jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  read_at timestamptz,
  UNIQUE (user_id, source_event_id, notification_type)
);

CREATE TABLE identity.notification_deliveries (
  delivery_id uuid PRIMARY KEY,
  notification_id uuid NOT NULL REFERENCES identity.notifications(notification_id) ON DELETE CASCADE,
  channel varchar(12) NOT NULL CHECK (channel IN ('EMAIL','IN_APP')),
  status varchar(12) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','SENT','FAILED')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_attempt_at timestamptz NOT NULL DEFAULT now(),
  sent_at timestamptz,
  provider_message_id text,
  UNIQUE (notification_id, channel)
);

CREATE TABLE identity.data_deletion_requests (
  deletion_request_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES identity.users(user_id),
  policy_version varchar(40) NOT NULL,
  status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','PROCESSING','COMPLETED','FAILED')),
  requested_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  error_summary text
);

CREATE TABLE identity.data_deletion_acks (
  deletion_request_id uuid NOT NULL REFERENCES identity.data_deletion_requests(deletion_request_id),
  service_name varchar(20) NOT NULL CHECK (service_name IN ('identity','catalog','community','trip','intelligence','ingestion')),
  status varchar(16) NOT NULL CHECK (status IN ('PENDING','COMPLETED','FAILED')),
  artifact_result jsonb NOT NULL DEFAULT '{}',
  updated_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (deletion_request_id, service_name)
);

CREATE INDEX users_status_created_idx ON identity.users(status, created_at, user_id);
CREATE INDEX user_roles_role_idx ON identity.user_roles(role_code, user_id);
CREATE INDEX sessions_user_idx ON identity.auth_sessions(user_id, expires_at);
CREATE INDEX refresh_session_idx ON identity.refresh_tokens(session_id);
CREATE INDEX account_tokens_user_idx ON identity.account_tokens(user_id, purpose);
CREATE INDEX notifications_user_idx ON identity.notifications(user_id, created_at DESC, notification_id);
CREATE INDEX notification_retry_idx ON identity.notification_deliveries(next_attempt_at) WHERE status = 'PENDING';
CREATE UNIQUE INDEX one_live_deletion_request_idx ON identity.data_deletion_requests(user_id) WHERE status IN ('PENDING','PROCESSING');

-- Infrastructure tables local to this service; no cross-database access.
CREATE TABLE identity.outbox_events (
  event_id uuid PRIMARY KEY,
  aggregate_type varchar(80) NOT NULL,
  aggregate_id varchar(160) NOT NULL,
  aggregate_version bigint NOT NULL CHECK (aggregate_version > 0),
  event_type varchar(120) NOT NULL,
  schema_version integer NOT NULL DEFAULT 1 CHECK (schema_version > 0),
  payload jsonb NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  available_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE identity.inbox_events (
  consumer_name varchar(100) NOT NULL,
  event_id uuid NOT NULL,
  processed_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer_name, event_id)
);
CREATE TABLE identity.audit_logs (
  audit_id uuid PRIMARY KEY,
  actor_id uuid,
  actor_type varchar(20) NOT NULL,
  entity_type varchar(80) NOT NULL,
  entity_id varchar(160) NOT NULL,
  action varchar(80) NOT NULL,
  old_value jsonb,
  new_value jsonb,
  correlation_id uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE identity.idempotency_records (
  scope varchar(100) NOT NULL,
  actor_key varchar(160) NOT NULL,
  idempotency_key varchar(160) NOT NULL,
  request_hash varchar(64) NOT NULL,
  response_status smallint NOT NULL CHECK (response_status BETWEEN 100 AND 599),
  response_body jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  PRIMARY KEY (scope, actor_key, idempotency_key),
  CHECK (expires_at > created_at)
);
CREATE INDEX outbox_pending_idx ON identity.outbox_events(available_at, occurred_at) WHERE published_at IS NULL;
CREATE INDEX audit_entity_idx ON identity.audit_logs(entity_type, entity_id, created_at);
CREATE INDEX idempotency_expiry_idx ON identity.idempotency_records(expires_at);
